    function initVisitOutcomesChart() { destroyChart('visitOutcomes'); chartInstances.visitOutcomes = new ApexCharts(document.querySelector("#visitOutcomesChart"), { series: [55, 25, 15, 5], chart: { type: 'donut', height: 280, redrawOnWindowResize: true }, labels: ['Resolved (55%)', 'Follow-up Required (25%)', 'Referred to Specialist (15%)', 'Hospitalized (5%)'], colors: ['#0088FE', '#00C49F', '#FFBB28', '#FF8042'], legend: { position: 'bottom' } }).render(); }
    function initAgeDistributionChart() { destroyChart('ageDistribution'); chartInstances.ageDistribution = new ApexCharts(document.querySelector("#ageDistributionChart"), { series: [{ name: 'Patients', data: [15, 28, 32, 18, 7] }], chart: { type: 'bar', height: 280 }, xaxis: { categories: ['0-18', '19-35', '36-50', '51-65', '65+'] }, colors: ['#8884d8'], plotOptions: { bar: { borderRadius: 8 } } }).render(); }
    function initGenderDistributionChart() { destroyChart('genderDistribution'); chartInstances.genderDistribution = new ApexCharts(document.querySelector("#genderDistributionChart"), { series: [52, 44, 4], chart: { type: 'donut', height: 280, redrawOnWindowResize: true }, labels: ['Female (52%)', 'Male (44%)', 'Other (4%)'], colors: ['#0088FE', '#00C49F', '#FFBB28'], legend: { position: 'bottom' } }).render(); }
    function initMonthlyTrendsChart() { destroyChart('monthlyTrends'); chartInstances.monthlyTrends = new ApexCharts(document.querySelector("#monthlyTrendsChart"), { series: [{ name: 'Total Visits', data: [280, 310, 345, 380, 365, 340] }, { name: 'New Patients', data: [32, 38, 42, 48, 45, 40] }], chart: { type: 'line', height: 280 }, xaxis: { categories: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'] }, colors: ['#6366f1', '#10b981'] }).render(); }
    function initDayDistributionChart() { destroyChart('dayDistribution'); chartInstances.dayDistribution = new ApexCharts(document.querySelector("#dayDistributionChart"), { series: [{ name: 'Visits', data: [185, 210, 225, 195, 175, 95, 65] }], chart: { type: 'bar', height: 280 }, xaxis: { categories: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'] }, colors: ['#6366f1'], plotOptions: { bar: { borderRadius: 8 } } }).render(); }
    function initTopConditionsChart() { destroyChart('topConditions'); chartInstances.topConditions = new ApexCharts(document.querySelector("#topConditionsChart"), { series: [32, 24, 18, 14, 12], chart: { type: 'donut', height: 280, redrawOnWindowResize: true }, labels: ['Hypertension (32%)', 'Diabetes (24%)', 'Respiratory (18%)', 'Arthritis (14%)', 'Anxiety (12%)'], colors: ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8'], legend: { position: 'bottom' } }).render(); }
    function initConditionTrendsChart() { destroyChart('conditionTrends'); chartInstances.conditionTrends = new ApexCharts(document.querySelector("#conditionTrendsChart"), { series: [{ name: 'Hypertension', data: [42, 45, 48, 52, 55, 58] }, { name: 'Diabetes', data: [28, 30, 32, 35, 37, 40] }, { name: 'Respiratory', data: [35, 38, 42, 38, 35, 32] }], chart: { type: 'line', height: 280 }, xaxis: { categories: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'] }, colors: ['#0088FE', '#00C49F', '#FFBB28'] }).render(); }

    function getFilteredAndSortedVisits() {
        let filtered = recentVisits.filter(v => {
            if (departmentFilter !== 'all' && v.department !== departmentFilter) return false;
            if (doctorFilter !== 'all' && v.doctor !== doctorFilter) return false;
            if (searchQuery && !v.patient.toLowerCase().includes(searchQuery.toLowerCase())) return false;
            if (dateRange.start && dateRange.end && (v.date < dateRange.start || v.date > dateRange.end)) return false;
            return true;
        });
        filtered.sort((a, b) => {
            let aVal = a[currentSort.field], bVal = b[currentSort.field];
            if (currentSort.field === 'date') { aVal = a.date; bVal = b.date; }
            if (aVal < bVal) return currentSort.direction === 'asc' ? -1 : 1;
            if (aVal > bVal) return currentSort.direction === 'asc' ? 1 : -1;
            return 0;
        });
        return filtered;
    }

    function renderTables() {
        let filteredVisits = getFilteredAndSortedVisits();
        document.getElementById('recentVisitsTable').innerHTML = filteredVisits.map(v => `<tr class="border-b  hover:bg-accent hover:text-accent-foreground h-10"><td class="p-4 font-medium">${v.patient}</td><td class="p-4">${v.displayDate}</td><td class="p-4">${v.department}</td><td class="p-4">${v.doctor}</td><td class="p-4">${v.type}</td><td class="p-4"><span class="inline-flex rounded-full px-2 py-0.5 text-xs font-semibold bg-green-100 text-green-800">${v.status}</span></td></tr>`).join('') || '<tr><td colspan="6" class="p-8 text-center text-gray-500">No visits found</td></tr>';
        
        document.getElementById('geoTable').innerHTML = geoData.map(g => `<tr class="border-b  hover:bg-accent hover:text-accent-foreground h-10"><td class="p-4 font-medium">${g.location}</td><td class="p-4">${g.patients}</td><td class="p-4">${g.percent}</td><td class="p-4">${g.avgVisits}</td><td class="p-4${g.changeUp ? 'text-green-500' : 'text-red-500'}"><div class="flex items-center"><svg class="h-4 w-4 mr-1" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="${g.changeUp ? 'm5 12 7-7 7 7M12 19V5' : 'M12 5v14M19 12l-7 7-7-7'}"/></svg>${g.change}</div></td></tr>`).join('');
        
        document.getElementById('frequencyTable').innerHTML = frequencyData.map(f => `<tr class="border-b  hover:bg-accent hover:text-accent-foreground h-10"><td class="p-4 font-medium">${f.frequency}</td><td class="p-4">${f.patients}</td><td class="p-4">${f.percent}</td><td class="p-4">${f.avgDuration}</td><td class="p-4${f.changeUp ? 'text-green-500' : 'text-red-500'}"><div class="flex items-center"><svg class="h-4 w-4 mr-1" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="${f.changeUp ? 'm5 12 7-7 7 7M12 19V5' : 'M12 5v14M19 12l-7 7-7-7'}"/></svg>${f.change}</div></td></tr>`).join('');
        
        document.getElementById('conditionDeptTable').innerHTML = conditionDept.map(c => `<tr class="border-b  hover:bg-accent hover:text-accent-foreground h-10"><td class="p-4 font-medium">${c.dept}</td><td class="p-4">${c.condition}</td><td class="p-4">${c.cases}</td><td class="p-4">${c.percent}</td><td class="p-4">${c.avgVisits}</td><td class="p-4${c.changeUp ? 'text-green-500' : 'text-red-500'}"><div class="flex items-center"><svg class="h-4 w-4 mr-1" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="${c.changeUp ? 'm5 12 7-7 7 7M12 19V5' : 'M12 5v14M19 12l-7 7-7-7'}"/></svg>${c.change}</div></td></tr>`).join('');
    }

    // Sort functionality
    document.querySelectorAll('.sort-indicator').forEach(el => {
        el.addEventListener('click', () => {
            const field = el.dataset.sort;
            if (currentSort.field === field) {
                currentSort.direction = currentSort.direction === 'asc' ? 'desc' : 'asc';
            } else {
                currentSort.field = field;
                currentSort.direction = 'desc';
            }
            renderTables();
            showToast(`Sorted by ${field} (${currentSort.direction === 'asc' ? 'ascending' : 'descending'})`);
        });
    });

    // Filter Popover
    function showFilterPopover(btn, type) {
        closePopover(); const rect = btn.getBoundingClientRect(); const popover = document.createElement('div'); popover.className = 'popover-content';
        let left = rect.left; let top = rect.bottom + 6;
        if (left + 260 > window.innerWidth) left = window.innerWidth - 270;
        if (top + 200 > window.innerHeight) top = rect.top - 220;
        popover.style.top = `${top}px`; popover.style.left = `${left}px`;
        if (type === 'visits') {
            popover.innerHTML = `<div class="popover-title">Filter Visits</div><div class="space-y-1"><div class="popover-option" data-filter="all">All Visits</div><div class="popover-option" data-filter="completed">Completed Only</div><div class="popover-option" data-filter="scheduled">Scheduled</div><div class="popover-option" data-filter="canceled">Canceled</div></div>`;
            popover.querySelectorAll('.popover-option').forEach(opt => { opt.addEventListener('click', () => { showToast(`Filter: ${opt.textContent}`); closePopover(); }); });
        } else if (type === 'frequency') {
            popover.innerHTML = `<div class="popover-title">Filter Frequency</div><div class="space-y-1"><div class="popover-option" data-filter="all">All Frequencies</div><div class="popover-option" data-filter="first">First-time</div><div class="popover-option" data-filter="regular">2-10 visits</div><div class="popover-option" data-filter="frequent">10+ visits</div></div>`;
            popover.querySelectorAll('.popover-option').forEach(opt => { opt.addEventListener('click', () => { showToast(`Filter: ${opt.textContent}`); closePopover(); }); });
        }
        document.body.appendChild(popover); activePopover = popover;
        const closeHandler = (e) => { if (!popover.contains(e.target) && e.target !== btn) { closePopover(); document.removeEventListener('click', closeHandler); } };
        setTimeout(() => document.addEventListener('click', closeHandler), 10);
    }

    // Date Range Picker
    const dateBtn = document.getElementById('dateRangeBtn'), datePicker = document.getElementById('datePickerPopover');
    dateBtn?.addEventListener('click', (e) => { e.stopPropagation(); datePicker.classList.toggle('hidden'); });
    document.getElementById('applyDateBtn')?.addEventListener('click', () => { const start = document.getElementById('startDate').value, end = document.getElementById('endDate').value; if(start && end) { dateRange = { start, end }; document.getElementById('dateRangeText').textContent = `${new Date(start).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })} - ${new Date(end).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`; datePicker.classList.add('hidden'); renderTables(); showToast('Date range applied'); } });
    document.getElementById('cancelDateBtn')?.addEventListener('click', () => datePicker.classList.add('hidden'));
    document.addEventListener('click', (e) => { if (!dateBtn?.contains(e.target) && !datePicker?.contains(e.target)) datePicker?.classList.add('hidden'); });

    // Filter Dropdowns
    function initFilter(btnId, dropdownId, textId, setter) {
        const btn = document.getElementById(btnId), dropdown = document.getElementById(dropdownId), text = document.getElementById(textId);
        if(!btn) return;
        btn.addEventListener('click', (e) => { e.stopPropagation(); dropdown.classList.toggle('hidden'); });
        dropdown.querySelectorAll('.select-item').forEach(item => { item.addEventListener('click', () => { text.textContent = item.textContent; const val = item.dataset.value; if(setter === 'dept') departmentFilter = val; else doctorFilter = val; dropdown.classList.add('hidden'); renderTables(); }); });
        document.addEventListener('click', (e) => { if(!btn.contains(e.target) && !dropdown.contains(e.target)) dropdown.classList.add('hidden'); });
    }
    initFilter('deptFilterBtn', 'deptFilterDropdown', 'deptFilterText', 'dept');
    initFilter('doctorFilterBtn', 'doctorFilterDropdown', 'doctorFilterText', 'doctor');

    document.getElementById('searchInput')?.addEventListener('input', (e) => { searchQuery = e.target.value; renderTables(); });
    document.getElementById('refreshBtn')?.addEventListener('click', () => { renderTables(); showToast('Data refreshed'); });
    document.getElementById('exportBtn')?.addEventListener('click', () => { 
        const data = getFilteredAndSortedVisits();
        const headers = ['Patient', 'Visit Date', 'Department', 'Doctor', 'Visit Type', 'Status'];
        const rows = data.map(v => [v.patient, v.displayDate, v.department, v.doctor, v.type, v.status]);
        const csv = [headers.join(','), ...rows.map(row => row.map(c => `"${c}"`).join(','))].join('\n');
        const blob = new Blob([csv], { type: 'text/csv' }); const a = document.createElement('a');
        a.href = URL.createObjectURL(blob); a.download = `patient_visits_${new Date().toISOString().slice(0,10)}.csv`;
        a.click(); URL.revokeObjectURL(a.href); showToast('Export complete');
    });
    document.getElementById('filterVisitsBtn')?.addEventListener('click', (e) => showFilterPopover(e.currentTarget, 'visits'));
    document.getElementById('filterFreqBtn')?.addEventListener('click', (e) => showFilterPopover(e.currentTarget, 'frequency'));
    document.getElementById('sortVisitsBtn')?.addEventListener('click', () => showToast('Click on column headers to sort'));
    document.getElementById('exportGeoBtn')?.addEventListener('click', () => showToast('Export complete'));
    document.getElementById('exportConditionBtn')?.addEventListener('click', () => showToast('Export complete'));

    // Tab switching
    function activateTab(tabId) {
        ['overview', 'demographics', 'trends', 'conditions'].forEach(t => {
            const panel = document.getElementById(`tab-${t}`); const btn = document.querySelector(`.tab-btn[data-tab="${t}"]`);
            if(panel) panel.setAttribute('data-state', t === tabId ? 'active' : 'inactive');
            if(btn) { if(t === tabId) btn.classList.add('active'); else btn.classList.remove('active'); }
        });
        if(tabId === 'overview') { initVisitTypesChart(); initVisitOutcomesChart(); }
        else if(tabId === 'demographics') { initAgeDistributionChart(); initGenderDistributionChart(); }
        else if(tabId === 'trends') { initMonthlyTrendsChart(); initDayDistributionChart(); }
        else if(tabId === 'conditions') { initTopConditionsChart(); initConditionTrendsChart(); }
    }
    document.querySelectorAll('.tab-btn').forEach(btn => btn.addEventListener('click', () => activateTab(btn.dataset.tab)));


    renderTables();
    initVisitTypesChart();
    initVisitOutcomesChart();

    function refreshAllCharts() {
        setTimeout(() => { window.dispatchEvent(new Event('resize')); }, 350);
    }
    document.querySelector('.lucide-menu')?.closest('button')?.addEventListener('click', refreshAllCharts);
</script>

    
    


